Here's a test suite that pins down the current behavior *and* documents where the implementation is likely to surprise you.

**`slugify.py`** (your function, unchanged):

```python
def slugify(s):
    return s.lower().replace(' ', '-')
```

**`test_slugify.py`**:

```python
"""Tests for the naive slugify(): s.lower().replace(' ', '-')"""

import pytest

from slugify import slugify


# ---------------------------------------------------------------- basics

class TestHappyPath:
    def test_title_case_words(self):
        assert slugify("Hello World") == "hello-world"

    def test_single_word_is_only_lowercased(self):
        assert slugify("HELLO") == "hello"

    def test_already_lower(self):
        assert slugify("hello") == "hello"

    def test_mixed_case_preserves_inner_letters(self):
        assert slugify("HtTp S 3rv1ce") == "http-s-3rv1ce"

    def test_empty_string(self):
        assert slugify("") == ""

    def test_digits_are_kept(self):
        assert slugify("Python 3.11") == "python-3.11"

    def test_existing_hyphens_are_untouched(self):
        assert slugify("kebab-case already") == "kebab-case-already"

    def test_underscores_are_untouched(self):
        assert slugify("snake_case here") == "snake_case-here"


# ------------------------------------------------- whitespace behaviour

class TestWhitespace:
    @pytest.mark.parametrize(
        "text, expected",
        [
            (" a ", "-a-"),            # leading/trailing spaces become hyphens
            ("a  b", "a--b"),         # N spaces -> N hyphens (no collapsing)
            ("a   b     c", "a---b-----c"),
            ("   ", "---"),           # whitespace-only input -> all hyphens
            ("Hello  World ", "hello--world-"),
        ],
    )
    def test_spaces_become_one_hyphen_each(self, text, expected):
        assert slugify(text) == expected

    @pytest.mark.parametrize(
        "text, expected",
        [
            ("Foo\tBar", "foo\tbar"),     # tab survives
            ("Foo\nBar", "foo\nbar"),     # newline survives
            ("Foo\rBar", "foo\rbar"),     # carriage return survives
            ("Foo\xa0Bar", "foo\xa0bar"), # non-breaking space survives
            ("Foo\u2003Bar", "foo\u2003bar"),  # em space survives
        ],
    )
    def test_only_the_literal_space_is_replaced(self, text, expected):
        """Characterisation test: .replace(' ', '-') is ASCII-space-only."""
        assert slugify(text) == expected


# ----------------------------------------------------- other characters

class TestCharactersNotHandled:
    def test_punctuation_survives(self):
        assert slugify("Hello, World!") == "hello,-world!"

    def test_apostrophe_survives(self):
        assert slugify("Don't Stop Believin'") == "don't-stop-belin'"

    def test_accents_are_not_transliterated(self):
        assert slugify("Café au Lait") == "café-au-lait"

    def test_slash_is_kept_as_is(self):
        assert slugify("a/b c") == "a/b-c"

    def test_turkish_dotted_capital_i_expands_to_two_codepoints(self):
        """U+0130 lowercases to 'i' + U+0307 COMBINING DOT ABOVE, not 'i'."""
        assert slugify("Istanbul") == "istanbul"
        assert slugify("İstanbul") == "i\u0307stanbul"
        assert slugify("İstanbul") != "istanbul"

    def test_german_sharp_s_is_left_alone_under_lower(self):
        assert slugify("Straße") == "straße"


# ----------------------------------------------------------- properties

class TestInvariants:
    INPUTS = [
        "", "hello", "Hello World", "  spaced  out  ",
        "MiXeD CaSe 123", "already-a-slug", "Punct! Uate,",
        "Café au Lait", "a\nb\tc",
    ]

    @pytest.mark.parametrize("text", INPUTS)
    def test_result_contains_no_literal_spaces(self, text):
        assert " " not in slugify(text)

    @pytest.mark.parametrize("text", INPUTS)
    def test_result_is_lowercase(self, text):
        out = slugify(text)
        assert out == out.lower()

    @pytest.mark.parametrize("text", INPUTS)
    def test_result_length_equals_input_length(self, text):
        """1:1 char mapping — no stripping, no collapsing, no escaping."""
        assert len(slugify(text)) == len(text)

    @pytest.mark.parametrize("text", INPUTS)
    def test_idempotent(self, text):
        once = slugify(text)
        assert slugify(once) == once

    @pytest.mark.parametrize("text", INPUTS)
    def test_input_string_is_not_mutated(self, text):
        original = text
        slugify(text)
        assert text == original


# ---------------------------------------------------------------- types

class TestInputTypes:
    @pytest.mark.parametrize(
        "bad_input",
        [123, 1.5, None, True, ["Hello World"], ("Hello",), {"a": "b"}, b"Hello World"],
    )
    def test_non_str_raises_attribute_error(self, bad_input):
        """No type guard: the failure surfaces as AttributeError from .lower()."""
        with pytest.raises(AttributeError):
            slugify(bad_input)

    def test_bytes_are_rejected(self):
        with pytest.raises(AttributeError):
            slugify(b"Hello World")


# -------------------------------- desired-but-missing behaviour (red by design)

class TestKnownGaps:
    """These encode what callers usually *expect* from a slugify.
    Remove each xfail once the implementation is hardened."""

    @pytest.mark.xfail(reason="does not collapse runs of whitespace into one hyphen", strict=True)
    def test_collapses_multiple_spaces(self):
        assert slugify("a  b") == "a-b"

    @pytest.mark.xfail(reason="does not strip leading/trailing whitespace", strict=True)
    def test_strips_surrounding_whitespace(self):
        assert slugify("  hello world  ") == "hello-world"

    @pytest.mark.xfail(reason="only handles ' ', not \\t/\\n/\\xa0", strict=True)
    def test_handles_all_whitespace(self):
        assert slugify("a\tb\nc\xa0d") == "a-b-c-d"

    @pytest.mark.xfail(reason="does not drop punctuation", strict=True)
    def test_drops_non_alphanumeric(self):
        assert slugify("Hello, World!") == "hello-world"

    @pytest.mark.xfail(reason="does not transliterate accented characters", strict=True)
    def test_transliterates_accents(self):
        assert slugify("Café") == "cafe"

    @pytest.mark.xfail(reason="does not trim leading/trailing hyphens", strict=True)
    def test_no_leading_or_trailing_hyphen(self):
        assert slugify(" hello ") == "hello"

    @pytest.mark.xfail(reason="no max-length truncation", strict=True)
    def test_respects_max_length(self):
        assert len(slugify("word " * 200, max_length=50)) == 50
```

Run it:

```bash
pytest test_slugify.py -v          # xfail gap tests show as expected failures
pytest test_slugify.py --runxfail  # see them as real failures
```

Two things worth knowing before you ship this:

- The `TestKnownGaps` block is the interesting part — it fails today by design, so it acts as a spec for the rewrite. A hardened version is usually `re.sub(r"[^a-z0-9]+", "-", s.strip().casefold()).strip("-")` (plus `unicodedata` normalization if you need ASCII slugs).
- The `TestInvariants` and `TestCharactersNotHandled` classes assert the *current* behavior, including the ugly bits (`--`, `-a-`, tabs surviving, `İ` → `i̇`). If you change the implementation, decide deliberately which of those you keep rather than letting them break silently.
